import json
        import os
        from pathlib import Path
        declared = os.environ.get("VLLM_OMNI_CHECKPOINT_PATHS")
        if declared is not None:
            roots = json.loads(declared)
            if not isinstance(roots, list) or not roots or not all(
                isinstance(root, str) and Path(root).is_absolute() and Path(root).is_dir()
                for root in roots
            ):
                raise ValueError("VLLM_OMNI_CHECKPOINT_PATHS must bind existing absolute checkpoint directories")
        else:
            roots = [os.environ.get("HF_HUB_CACHE") or os.environ.get("HUGGINGFACE_HUB_CACHE")
                     or str(Path.home() / ".cache/huggingface/hub")]
        advised = set()
        for root in roots:
            for candidate in Path(root).rglob("*"):
                if not candidate.is_file():
                    continue
                path = candidate.resolve(strict=True)
                if path in advised or path.stat().st_size < 64 * 1024 * 1024:
                    continue
                fd = os.open(path, os.O_RDONLY)
                try:
                    os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)
                    advised.add(path)
                finally:
                    os.close(fd)
        return int(torch.cuda.mem_get_info(self.device)[0])
